Q: How to apply modifier or view by condition A: <h1>Solution 1: if / else</h1>
<pre><code>@available(OSX 11.0, *)
public extension View {
    @ViewBuilder
    func `if`&lt;Content: View&gt;(_ condition: Bool, @ViewBuilder content: (Self) -&gt; Content) -&gt; some View {
        if condition {
            content(self)
        } else {
            self
        }
    }

    @ViewBuilder
    func `if`&lt;TrueContent: View, FalseContent: View&gt;(_ condition: Bool, @ViewBuilder ifTrue trueContent: (Self) -&gt; TrueContent, @ViewBuilder else falseContent: (Self) -&gt; FalseContent) -&gt; some View {
        if condition {
            trueContent(self)
        } else {
            falseContent(self)
        }
    }
}
</code></pre>
<p>Usage example ( if ) :</p>
<pre><code>Text(&quot;some Text&quot;)
   .if(condition) { $0.foregroundColor(.red) }
   .bold()
</code></pre>
<p>Usage example2 ( if/else ) :</p>
<pre><code>Text(&quot;some Text&quot;)
   .if(condition) { $0.foregroundColor(.red) } 
    else:         { $0.foregroundColor(.blue).background(.green) }
   .bold()
</code></pre>
<h1>Solution 2 <code>.modify{ }</code></h1>
<pre><code>public extension View {
    func modify(@ViewBuilder _ modifier: (Self) -&gt; some View) -&gt; some View {
        return modifier(self)
    }
}
</code></pre>
<p>usage:</p>
<pre><code>Text(&quot;some Text&quot;)
   .bold()
   .modify { view in
       if condition {
           view.foregroundColor(.red)
       } else { // do not forget about &quot;else&quot; or you can get empty view!
           view
       }
   }
   .padding()
   .background(.blue)


</code></pre>

Q: Spring Boot 4: How to define ObjectMapper based on autoconfiguration? A: <p>While Spring Boot 4 (and its underlying Spring Framework 7) pushes for more immutable configurations and functional bean registrations, the Jackson2ObjectMapperBuilderCustomizer remains the primary &quot;safe&quot; hook to modify the ObjectMapper without blowing away the auto-configuration.</p>
<pre><code>@Bean
public Jackson2ObjectMapperBuilderCustomizer caseInsensitiveCustomizer() {
    return builder -&gt; {
        builder.featuresToEnable(MapperFeature.ACCEPT_CASE_INSENSITIVE_PROPERTIES);
    };
}
</code></pre>
